// We use the Verus verification framework
verus! {

    // solve: given a, b ∈ i8 with -100 ≤ a, b ≤ 100 and
    // both a+b and a−b even, find x,y ∈ i8 such that
    //   a = x + y
    //   b = x − y
    //
    // Signature matches: fn solve(a: i8, b: i8) -> (result: (i8, i8))
    fn solve(a: i8, b: i8) -> (result: (i8, i8))
        // Preconditions on inputs
        requires
            -100 <= (a as int) && (a as int) <= 100,
            -100 <= (b as int) && (b as int) <= 100,
            // parity conditions: sum and difference even
            ((a as int + b as int) % 2) == 0,
            ((a as int - b as int) % 2) == 0,
        // Postconditions: result.0 + result.1 == a, result.0 - result.1 == b
        ensures
            result.0 as int + result.1 as int == a as int,
        ensures
            result.0 as int - result.1 as int == b as int,
    {
        // Compute the unique solution:
        //   x = (a + b)/2,  y = (a - b)/2
        let sum_i: int = (a as int + b as int) / 2;
        let diff_i: int = (a as int - b as int) / 2;

        // Show they fit in i8 range, so the casts are safe
        assert(-128 <= sum_i && sum_i <= 127);
        assert(-128 <= diff_i && diff_i <= 127);

        let x: i8 = sum_i as i8;
        let y: i8 = diff_i as i8;

        // Verify they satisfy the required equations
        assert(x as int + y as int == a as int);
        assert(x as int - y as int == b as int);

        (x, y)
    }
}